def esc(x): return str(x).replace('&','&amp;').replace('<','&lt;').replace('>','&gt;')
def P(x, st='body'): return Paragraph(esc(x).replace('\n','<br/>'), S[st])
def bullets(xs): return KeepTogether([P('- '+x) for x in xs])
def fill_for(x): return {'P0':RED,'P1':AMBER,'P2':BLUE,'P3':MUTED,'DONE':GREEN,'PARTIAL':AMBER,'MISSING':RED,'PLANNED':PURPLE,'UNVERIFIED':BLUE,'BLOCKED':RED,'Implemented':GREEN,'Partial':AMBER,'Missing':RED,'Planned':PURPLE,'Unverified':BLUE}.get(x,MUTED)
def badge(x): return Paragraph('<b>'+esc(x)+'</b>', ParagraphStyle('b'+x, parent=S['badge'], backColor=fill_for(x), borderPadding=(3,5,3,5)))

def on_page(c,d):
    c.saveState(); c.setFillColor(BG); c.rect(0,0,A4[0],A4[1],fill=1,stroke=0)
    c.setStrokeColor(LINE); c.setLineWidth(.5); c.line(17*mm,A4[1]-15*mm,A4[0]-17*mm,A4[1]-15*mm); c.line(17*mm,13*mm,A4[0]-17*mm,13*mm)
    c.setFont('Helvetica-Bold',7); c.setFillColor(MUTED); c.drawString(17*mm,A4[1]-11*mm,'OMNILUME')
    c.setFont('Helvetica',7); c.drawRightString(A4[0]-17*mm,A4[1]-11*mm,'PRODUCT BLUEPRINT'); c.drawString(17*mm,8*mm,'Source-led planning document | Extend first, verify every layer')
    c.drawRightString(A4[0]-17*mm,8*mm,str(d.page)); c.restoreState()

def make_doc(path):
    fr=Frame(17*mm,19*mm,A4[0]-34*mm,A4[1]-39*mm,leftPadding=0,rightPadding=0,topPadding=5*mm,bottomPadding=0,id='f')
    d=BaseDocTemplate(path,pagesize=A4,leftMargin=17*mm,rightMargin=17*mm,topMargin=19*mm,bottomMargin=19*mm,title='OmniLume')
    d.addPageTemplates([PageTemplate(id='dark',frames=fr,onPage=on_page)]); return d

def tbl(headers, rows, widths, color=CYAN):
    data=[[Paragraph(esc(x),S['head']) for x in headers]]+[[Paragraph(esc(x),S['cell']) for x in r] for r in rows]
    t=Table(data,colWidths=widths,repeatRows=1,hAlign='LEFT')
    cmds=[('BACKGROUND',(0,0),(-1,0),color),('GRID',(0,0),(-1,-1),.35,LINE),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5)]
    for i in range(1,len(data)): cmds.append(('BACKGROUND',(0,i),(-1,i),PANEL2 if i%2==0 else PANEL))
    t.setStyle(TableStyle(cmds)); return t

def card(title, lines, accent=CYAN, width=177*mm):
    body=[x if hasattr(x,'wrapOn') else P(x) for x in lines] if isinstance(lines,list) else P(lines)
    t=Table([[P(title,'h3')],[body]],colWidths=[width])
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),PANEL),('BOX',(0,0),(-1,-1),.6,LINE),('LINEBEFORE',(0,0),(0,-1),3,accent),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7)])); return t

def two(a_title,a_lines,b_title,b_lines):
    a=card(a_title,[P(x) for x in a_lines],CYAN,84*mm); b=card(b_title,[P(x) for x in b_lines],PURPLE,84*mm)
    t=Table([[a,b]],colWidths=[87*mm,87*mm]); t.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),0),('RIGHTPADDING',(0,0),(-1,-1),5)])); return t

def cover(story,title,subtitle,kicker,facts):
    story += [Spacer(1,34*mm),P(kicker,'coverk'),P(title,'covert'),P(subtitle,'covers'),Spacer(1,9*mm)]
    rows=[[P(k,'small'),P(v)] for k,v in facts]; t=Table(rows,colWidths=[38*mm,115*mm])
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),PANEL),('BOX',(0,0),(-1,-1),.7,LINE),('INNERGRID',(0,0),(-1,-1),.35,LINE),('TEXTCOLOR',(0,0),(0,-1),CYAN),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),8),('BOTTOMPADDING',(0,0),(-1,-1),8)])); story += [t,Spacer(1,20*mm),P('Protect the existing codebase. Extend first. Verify source, runtime, security, multi-user, and production behavior separately.','covers'),PageBreak()]

