canonical_new=[
'Edit/delete own messages','Shared PDFs','Invite link + unique code','Live shared notes','Timer-created owner notification','Member 3-dot actions','Ghost Mode','Voice chat + owner mute','Room Control Center','Room Roles & Permissions','Room Announcements','Pinned Messages','Message Replies / Threads','Mentions','Notification Center','Room Search','Activity / Room History','Custom Room Layout Presets','Owner-controlled room UI/layout','Room Themes / Appearance','Polls & Voting','Shared Queue','Now Playing / Shared State Bar','User Presence States','Leave / Kick / Ban / Block','Screen Sharing','Raise Hand','Room Rules & Welcome Message','Temporary Guest Access','Room Lock','Scheduled Rooms','Room Events','Shared Whiteboard Cursor Presence','Collaborative Document Editing','Room Bookmarks / Saved Content','Room-Specific User Profiles','Smart Room Search & Filters','Room Backup / Export','Shared Countdown / Event Timer','Live Activity Bar','Room Dashboard / Home','Room Clips / Highlights','Smart Auto-Organization','Room Templates','Guest / Temporary Identity Mode','Room Reputation / Trust Levels','Smart Notification Controls / Do Not Disturb','Cross-Room Personal Dashboard','AI Room Assistant','Live AI Meeting Assistant','AI-assisted Action Items / Tasks','Automated Room Summary','Meeting Minutes / Meeting Summary','Room Memory'
]

def canonical_owner(label):
    if label in ['Room Search','Activity / Room History','Smart Room Search & Filters','Room Backup / Export','Live Activity Bar','Room Dashboard / Home','Smart Auto-Organization','Room Templates','Room Reputation / Trust Levels','Cross-Room Personal Dashboard']: return '13'
    if label.startswith('AI') or label.startswith('Automated') or label.startswith('Meeting Minutes') or label=='Room Memory': return '17'
    if label in ['Shared PDFs','Shared Whiteboard Cursor Presence','Collaborative Document Editing','Shared Countdown / Event Timer']: return '10/12'
    if label in ['Shared Queue','Now Playing / Shared State Bar','Room Clips / Highlights']: return '11'
    if label in ['Live shared notes','Polls & Voting','Screen Sharing','Raise Hand','Room Events','Scheduled Rooms','Voice chat + owner mute','Timer-created owner notification']: return '12'
    if label in ['Edit/delete own messages','Member 3-dot actions','Room Announcements','Pinned Messages','Message Replies / Threads','Mentions','Notification Center','Smart Notification Controls / Do Not Disturb']: return '08'
    return '05/09'

def canonical_status(label):
    if label in ['Edit/delete own messages','Shared PDFs','Room Search','Voice chat + owner mute']: return 'Partial'
    if label.startswith('AI') or label.startswith('Automated') or label.startswith('Meeting Minutes') or label=='Room Memory': return 'Planned'
    return 'Missing'

