    right=[P(title,'atitle'),Spacer(1,3),Table([[badge(priority),badge(status)]],colWidths=[24*mm,30*mm],style=TableStyle([('LEFTPADDING',(0,0),(-1,-1),0),('RIGHTPADDING',(0,0),(-1,-1),4)]))]
    t=Table([[left,right]],colWidths=[27*mm,151*mm]); t.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'MIDDLE'),('LEFTPADDING',(0,0),(-1,-1),0),('RIGHTPADDING',(0,0),(-1,-1),0),('TOPPADDING',(0,0),(-1,-1),0),('BOTTOMPADDING',(0,0),(-1,-1),3)])); return t

